        for (const { path, mark } of marked) {
            if (!notes.has(mark.id))
                continue;
            try {
                const change = oneWaySuspendChange(path, mark, cards.get(mark.id) ?? []);
                if (change && this.reviewOperation(path, change.operation, describe))
                    approved.push(change);
            }
            catch (error) {
                this.retry(path, String(error));
            }
        }
