                if (request.signal.aborted)
                    return;
                loaded = false;
                deckNames = [];
                deckPicker.setChoices([]);
                deckStatus.setText(t('Anki decks are unavailable. Open Anki and reload to choose a new deck.', 'Колоды недоступны. Откройте Anki и обновите список колод.'));
